import os, re
def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    path = os.path.normpath(d + '/../../sessions/' + os.path.basename(d) + '.jsonl')
    try:
        text = open(path).read()
    except:
        return {}
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
        k, h, w = m[1], int(m[2]), int(m[3])
        rest = text[m.end():].split('\n')[:h]
        rows = [r.split() for r in rest if r.strip()]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

